//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/jquery-1.11.0.min.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/elastic_search.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
scwin.contnId;
scwin.gRegId;
scwin.vScrenID = "ULDSTF60012.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_setInit = function() {
    var arrCid = [{
        cid: "LIST_INVSTG_ISUE_TP_CD",
        cnm: "cmb_IsueTp"
    }];
    var objCod;
    var url = "/CodeAction.do?method=listCodeValueNameM";
    url += "&inputMessageId=CODE_M_IN&outputMessageId=CODE_M_OUT";
    url += "&CD_ID_M='LIST_INVSTG_ISUE_TP_CD'";
    dts_Code.DataID = encodeURI(url);
    dts_Code.reset();
    buttonSet.setSaveInfo(btn_Save, fn_save);
    buttonSet.setUpdateInfo(btn_Update, fn_update);
    buttonSet.setDeleteInfo(btn_Delete, fn_delete);
};
scwin.fn_SetHeader = function() {
    dts_issue.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=LISTING_INVSTG_ISSUE_INOUT";
    dts_issue.Reset();
    dts_issue.insertRow();
    dts_issuedtl.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=LISTING_INVSTG_ISSUE_DTL_INOUT";
    dts_issuedtl.Reset();
    //dts_issuedtl.AddRow();

    var url = "/listingCommon.do?method=listGeneral&outputMessageId=LISTING_INVSTG_ISSUE_DTL_YN_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.listinvstgissue.issuedtlyn.select" + "&{P}PARAM01=" + "" + "&{P}PARAM02=" + "";
    dts_issuedtlyn.DataID = encodeURI(url);
    dts_issuedtlyn.Reset();
    //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};
scwin.fn_list_sync = function() {
    trs_Read.Action = "/ListIssueAdm.do?method=listInvstgIssue" + "&CONTN_ID=" + scwin.contnId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    trs_Read.KeyValue = "JSP(O:pOutput1=dts_issue, O:pOutput2=dts_fileList)";
    trs_Read.Post();

    //키워드 정보
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=LISTING_INVSTG_ISSUE_DTL_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.listinvstgissue.issuedtl.select" + "&{P}PARAM01=" + scwin.contnId;
    dts_issuedtl.DataID = encodeURI(url);
    dts_issuedtl.Reset();

    //키워드 정보 YN
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=LISTING_INVSTG_ISSUE_DTL_YN_INOUT" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.listinvstgissue.issuedtlyn.select" + "&{P}PARAM01=" + scwin.contnId + "&{P}PARAM02=" + scwin.contnId;
    dts_issuedtlyn.DataID = encodeURI(url);
    dts_issuedtlyn.Reset();
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(cmb_IsueTp) == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "유형"));
        return false;
    }
    if (tbox_title.getValue() == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "제목"));
        tbox_title.focus();
        return false;
    }
    if (!scwin.checkMaxLength1(tbox_title, 200, "제목")) {
        tbox_title.focus();
        return false;
    }
    if (tarea_contn_contn.Text == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "내용"));
        tarea_contn_contn.focus();
        return false;
    }
    if (!scwin.checkMaxLength2(tarea_contn_contn, 2000, "내용")) {
        tarea_contn_contn.focus();
        return false;
    }
    return true;
};
scwin.fn_save = function() {
    if (dts_fileList.getCellData(1, "fileInfo") == "") {
        dts_fileList.Reset();
    }
    if (scwin.fn_CheckForm()) {
        var rtn = confirm('저장 하시겠습니까?');
        if (rtn == 1) {
            dts_issue.setCellData(1, "LIST_INVSTG_ISUE_TP_CD", $c.stf.getObjectValue(cmb_IsueTp));
            dts_issue.setCellData(1, "REG_ID", js_emp_no);
            dts_issue.setCellData(1, "REG_DEP_CD", js_dep_cd);
            dts_issue.setCellData(1, "REG_DDTM", tbox_wrt_ddtm);
            trs_Save.Action = "/ListIssueAdm.do?method=saveInvstgIssue" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
            trs_Save.KeyValue = "JSP(I:pInput=dts_issue,I:pInput1=dts_issuedtl,I:pFile=dts_fileList)";
            trs_Save.Post();
        }
    }
};
scwin.fn_update = function() {
    if (scwin.fn_CheckForm()) {
        var rtn = confirm('수정 하시겠습니까?');
        if (rtn == 1) {
            dts_issue.setCellData(1, "LIST_INVSTG_ISUE_CONTN_TP_CD", $c.stf.getObjectValue(cmb_IsueTp));
            dts_issue.setCellData(1, "REG_ID", js_emp_no);
            dts_issue.setCellData(1, "REG_DDTM", tbox_wrt_ddtm);
            trs_Update.Action = "/ListIssueAdm.do?method=updateInvstgIssue&CONTN_ID=" + scwin.contnId + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
            trs_Update.KeyValue = "JSP(I:pInput=dts_issue,I:pInput1=dts_issuedtl,I:pFile=dts_fileList)";
            trs_Update.Post();
        }
    }
};
scwin.fn_delete = function() {
    var rtn = confirm('삭제 하시겠습니까?');
    if (rtn == 1) {

        //dts_ContentsDel.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
        dts_ContentsDel.insertRow();
        dts_ContentsDel.setCellData(1, "CONTN_ID", scwin.contnId);
        dts_ContentsDel.setCellData(1, "REG_ID", js_emp_no);
        trs_Delete.Action = "/ListIssueAdm.do?method=deleteInvstgIssue" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        trs_Delete.KeyValue = "JSP(I:pInput=dts_ContentsDel)";
        trs_Delete.Parameters = "CONTN_ID=" + scwin.contnId + ",REG_ID=" + js_emp_no;
        trs_Delete.Post();
    }
};
scwin.fn_filedown = function(attach_seq) {
    location.href = "/filedownload.do?CONTN_ID=" + scwin.contnId + "&CONTN_SEQ=" + attach_seq + "&gubun=39";
};
scwin.checkMaxLength1 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getValue()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ]자 입니다.");
        obj.focus();
        return false;
    }
    return true;
};
scwin.checkMaxLength2 = function(obj, size, lbl) {
    var overLen = eval($c.stf.getStringSize(obj.getText()) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 항목의 최대입력은 [ " + size + " ]자 입니다.");
        obj.focus();
        return false;
    }
    return true;
};
scwin.fn_getRecentContnId = function() {
    var url = "/listingCommon.do?method=listGeneralForDynamicName&outputMessageId=LISTING_INVSTG_ISSUE_INOUT&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&SCREN_ID=" + scwin.vScrenID + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.listinvstgissue.recentinfo.select" + "&{P}V_REG_ID=" + js_emp_no;
    dts_issue.DataID = encodeURI(url);
    dts_issue.Reset();
};
scwin.indexingElasitcSearch = function() {
    if (scwin.contnId == "input") {
        scwin.fn_getRecentContnId();
        scwin.fn_list_sync();
    }
    list_invstg_isue_file(scwin.contnId);
};
scwin.fn_setParam = function() {
    var parentWin = $c.frame.path("../");
    var paramObj = parentWin.gParamObj;
    if (paramObj == undefined) return;
    $c.stf.setObjectValue(txb_ISUR_CD, paramObj.param0);
    $c.stf.setObjectValue(txb_BYCORP_SEQ, paramObj.param1);
    Q;
    $c.stf.setObjectValue(txb_COM_NM, paramObj.param2);
};


// Get checkBox DataSet
scwin.fn_GetPar = function(param_contnId, param_dts1, param_dts2) {
    param_contnId = scwin.contnId;
    $c.stf.CopyDataSet(dts_issuedtl, param_dts1);
    $c.stf.CopyDataSet(dts_issuedtlyn, param_dts2);
};



// Set checkBox DataSet
scwin.fn_SetPar = function(param_dts1, param_dts2) {
    $c.stf.CopyDataSet(param_dts1, dts_issuedtlyn);
    $c.stf.CopyDataSet(param_dts2, dts_issuedtl);
    for (i = 1; i <= dts_issuedtl.getTotalRow(); i++) {
        dts_issuedtl.setCellData(i, "CONTN_ID", scwin.contnId);
    }
};
scwin.trs_Read_OnFail = function() {
    $c.win.alert(trs_Read.ErrorMsg);
};
scwin.trs_Save_OnSuccess = async function() {
    scwin.indexingElasitcSearch();
    buttonSet.setUpdateStatus();
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "저장"));
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "저장"));
    $c.win.alert(trs_Save.ErrorMsg);
};
scwin.trs_Update_OnSuccess = async function() {
    scwin.indexingElasitcSearch();
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "수정"));
    //fn_list_sync= frame.Provider("../").fn_list_sync; 
    //fn_list_sync();
    await $c.frame.CloseFrame();
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
    $c.win.alert(trs_Update.ErrorMsg);
};
scwin.trs_Delete_OnSuccess = async function() {
    scwin.indexingElasitcSearch();
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    await $c.frame.CloseFrame();
};
scwin.trs_Delete_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
    $c.win.alert(trs_Delete.ErrorMsg);
};
scwin.inf_find_OnClick = function() {
    var filenm = dts_fileList.getCellData(dts_fileList.getRowPosition(), "filename");
    if (scwin.contnId == "input") {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        file_name.setValue(inf_find.getValue());
    } else {
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
        dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", dts_fileList.getRowPosition());
        file_name.setValue(inf_find.getValue());
    }
    if (inf_find.getValue() == "") {
        file_name.setValue(filenm);
    }
};
scwin.btn_lineadd_onclick = function() {
    dts_fileList.insertRow();
    inf_find.open();
    if (inf_find.getValue() != "") {
        if (scwin.contnId == "input") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            var seq = dts_fileList.getRowPosition();
            for (i = 0; i < dts_fileList.getTotalRow(); i++) {
                if (dts_fileList.getCellData(i, "ATTACH_SEQ") == seq) {
                    seq++;
                    i = 0;
                }
            }
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "ATTACH_SEQ", seq);
            file_name.setValue(inf_find.getValue());
        }
    } else {
        $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
    }
};
scwin.dts_issue_OnLoadError = function() {
    $c.win.alert('dts_issue.OnLoadError()');
};
scwin.dts_issue_OnLoadCompleted = function(rowcount) {
    if (rowcount > 0) {
        buttonSet.setUpdateStatus();
        scwin.gRegId = dts_issue.getCellData(0, "REG_ID");
        $c.stf.setObjectValue(cmb_IsueTp, dts_issue.getCellData(0, "LIST_INVSTG_ISUE_TP_CD"));
        scwin.contnId = dts_issue.getCellData(0, "CONTN_ID");
    }
};
scwin.btn_linedelete_onclick = function() {
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.btn_cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_keyword_srch_onclick = async function() {
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("KEYWORD", "/lstmgt/ULDSTF60013.gfm", "주요키워드 선택 ", 100, 10, 920, 580, "window");
};
scwin.grd_fileList_OnDblClick = function(row, colid) {
    if (dts_fileList.getRowStatus(dts_fileList.getRowPosition()) == 0) {
        scwin.fn_filedown(dts_fileList.getCellData(row, "ATTACH_SEQ"));
    }
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    scwin.fn_setInit();
    scwin.contnId = $c.frame.path("../").fn_getContnId();
    if (scwin.contnId != "input") {
        scwin.fn_list_sync();
    } else {
        scwin.fn_SetHeader();
        buttonSet.setInsertStatus();
    }
    var parentframeID = $c.stf.getQuery(frame.srcUrl, "frameID");
    if (parentframeID.indexOf('STF60000') != -1) {
        $c.stf.showObj(btn_Save, false);
        $c.stf.showObj(btn_Delete, false);
    }
    tbox_wrtr_emp_nm.setValue(js_emp_nm);
    tbox_reg_dep_nm.setValue(js_dep_nm);
    tbox_wrt_ddtm.setValue($c.ut.cGetToday("yyyy-mm-dd hh:mm:ss"));
};
